(async () => {
    const { DialogV2 } = foundry.applications.api;

    // 1. 获取目标
    const actor = token?.actor || game.user.character;
    if (!actor) return ui.notifications.warn("请先选择一个角色 (Token)！");

    const SYSTEM_ID = "xjzl-system";
    const allFlags = actor.flags[SYSTEM_ID] || {};

    // 2. 扫描并分类 Flags
    const categories = {
        "neigong_": "🧘 内功相关",
        "wuxue_": "⚔️ 武学相关",
        "weapon_": "🗡️ 武器状态",
        "armor_": "🛡️ 防具状态",
        "consumed_": "💊 消耗品记录",
        "other": "📂 其他数据"
    };

    const grouped = {
        "neigong_": [], "wuxue_": [], "weapon_": [], "armor_": [], "consumed_": [], "other": []
    };

    let totalCount = 0;

    for (const [key, value] of Object.entries(allFlags)) {
        let matched = false;
        for (const prefix of ["neigong_", "wuxue_", "weapon_", "armor_", "consumed_"]) {
            if (key.startsWith(prefix)) {
                grouped[prefix].push({ key, val: value });
                matched = true;
                break;
            }
        }
        if (!matched) {
            grouped["other"].push({ key, val: value });
        }
        totalCount++;
    }

    if (totalCount === 0) {
        return ui.notifications.info(`${actor.name} 身上没有任何系统标记。`);
    }

    // 3. 构建 HTML
    // 将 form 改为 div 容器，防止 Dialog 渲染时被剥离
    let content = `
    <style>
        .xjzl-flag-group { margin-bottom: 10px; border: 1px solid #ccc; border-radius: 4px; overflow: hidden; }
        .xjzl-flag-header { background: rgba(0,0,0,0.05); padding: 5px 8px; font-weight: bold; font-size: 0.9em; border-bottom: 1px solid #eee; }
        .xjzl-flag-item { display: flex; align-items: center; padding: 4px 8px; border-bottom: 1px dashed rgba(0,0,0,0.05); font-size: 0.85em; }
        .xjzl-flag-item:last-child { border-bottom: none; }
        .xjzl-flag-item label { margin-left: 8px; flex: 1; cursor: pointer; word-break: break-all; }
        .xjzl-flag-val { font-family: monospace; background: rgba(0,0,0,0.05); padding: 0 4px; border-radius: 2px; max-width: 100px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    </style>
    <p>检测到 <strong>${actor.name}</strong> 共有 ${totalCount} 条记录。</p>
    <div class="xjzl-flag-container">`;

    for (const [prefix, list] of Object.entries(grouped)) {
        if (list.length === 0) continue;

        content += `<div class="xjzl-flag-group">
            <div class="xjzl-flag-header">${categories[prefix]} (${list.length})</div>`;

        for (const item of list) {
            let displayVal = JSON.stringify(item.val);
            if(displayVal.length > 20) displayVal = displayVal.substring(0, 20) + "...";

            // 转义双引号，防止 HTML 属性截断
            const safeTitle = JSON.stringify(item.val).replace(/"/g, '&quot;');

            content += `
            <div class="xjzl-flag-item">
                <input type="checkbox" id="${item.key}" name="${item.key}" checked>
                <label for="${item.key}">${item.key}</label>
                <span class="xjzl-flag-val" title="${safeTitle}">${displayVal}</span>
            </div>`;
        }
        content += `</div>`;
    }
    content += `</div>`;

    // 4. 弹窗确认
    const result = await DialogV2.wait({
        window: { title: `🧹 清理标记: ${actor.name}`, icon: "fas fa-trash-alt", width: 400 },
        content: content,
        buttons: [{
            action: "delete",
            label: "删除选中项",
            icon: "fas fa-check",
            class: "damage-tool-btn", 
            callback: (event, button, dialog) => {
                // 使用 dialog.element 查找 div 容器
                const container = dialog.element.querySelector(".xjzl-flag-container");
                if (!container) return [];
                const checked = container.querySelectorAll('input[type="checkbox"]:checked');
                return Array.from(checked).map(input => input.name);
            }
        }],
        close: () => []
    });

    // 5. 执行删除
    if (result && result.length > 0) {
        let deletedCount = 0;
        for (const key of result) {
            // 安全检查
            if (actor.flags[SYSTEM_ID] && key in actor.flags[SYSTEM_ID]) {
                await actor.unsetFlag(SYSTEM_ID, key);
                deletedCount++;
            }
        }
        ui.notifications.info(`已清理 ${deletedCount} 条数据记录。`);
    }
})();

(async () => {
    // --- 配置区域 ---
    const CONFIG = {
        label: "气海真诀",   // 默认显示的文字
        distance: 10,        // 半径 (格)
        color: "#FFD700"    // 颜色 (金黄色)
    };

    const scene = canvas.scene;
    if (!scene) return ui.notifications.warn("当前没有场景！");

    // 1. 获取选中Token
    const token = canvas.tokens.controlled[0];
    if (!token) return ui.notifications.warn("请先选中一个角色(Token)来使用跟随光环。");

    // 2. 计算位置 (Token中心)
    const { x, y } = token.center;

    // 3. 计算实际距离
    const finalDistance = CONFIG.distance * (canvas.dimensions.distance || 1);

    // 4. 创建模板
    await scene.createEmbeddedDocuments("MeasuredTemplate", [{
        t: "circle",
        user: game.user.id,
        distance: finalDistance,
        direction: 0,
        x: x,
        y: y,
        fillColor: CONFIG.color,
        flags: {
            "xjzl-system": {
                label: CONFIG.label,
                sourceToken: token.id,
                sticky: true  // 开启跟随
            }
        }
    }]);
})();

(async () => {
    // --- 配置区域 ---
    const CONFIG = {
        label: "拭剑听风",   // 默认显示的文字
        distance: 3,        // 半径 (格)
        color: "#DC143C"    // 颜色 (猩红色)
    };

    const scene = canvas.scene;
    if (!scene) return ui.notifications.warn("当前没有场景！");

    // 1. 获取鼠标位置 (V13 API)
    const mousePos = canvas.mousePosition;
    if (!mousePos) return;

    // 2. 对齐网格中心
    const grid = canvas.grid;
    const offset = grid.getOffset(mousePos);
    const center = grid.getCenterPoint(offset);

    // 3. 计算实际距离
    const finalDistance = CONFIG.distance * (canvas.dimensions.distance || 1);

    // 4. 创建模板
    await scene.createEmbeddedDocuments("MeasuredTemplate", [{
        t: "circle",
        user: game.user.id,
        distance: finalDistance,
        direction: 0,
        x: center.x,
        y: center.y,
        fillColor: CONFIG.color,
        flags: {
            "xjzl-system": {
                label: CONFIG.label,
                sourceToken: null,
                sticky: false // 静态不跟随
            }
        }
    }]);
})();

(async () => {
    // 1. 获取宏助手
    const Macros = game.xjzl.Macros;
    if (!Macros) return ui.notifications.error("系统核心未加载。");

    // 2. 获取选中目标 (需选中2个)
    const tokens = canvas.tokens.controlled;
    if (tokens.length < 2) return ui.notifications.warn("请选中两个Token：\n1. 发起者 (吸取方)\n2. 对抗者 (被吸方)");

    const attacker = tokens[0].actor;
    const defender = tokens[1].actor;

    // 3. 发起请求
    await Macros.requestContest({
        attacker: attacker,
        defender: defender,
        type: "neixi",     // 攻方属性: 内息
        defType: "dingli", // 守方属性: 定力
        label: "吸星大法",

        // 🏆 自动化结果配置
        outcome: {
            // 发起者胜利
            win: {
                text: "你的丹田如黑洞般吞噬了对方的内力！",
                selfRecovery: { value: 50, type: "mp" }, // 自己回 50 内力
                targetDamage: { value: 50, type: "mp" }, // 对方扣 50 内力
                targetEffect: "weak" // 给对方上虚弱 (需系统内有此状态ID)
            },
            // 发起者失败
            lose: {
                text: "对方内力浑厚，你吸取不成反遭真气反噬！",
                selfDamage: { value: 20, type: "hp" }, // 自己扣 20 血
                selfEffect: "prone" // 自己倒地
            }
        }
    });
})();

(async () => {
    // 1. 获取目标
    const actor = token?.actor || game.user.character;
    if (!actor) return ui.notifications.warn("请先选择一个角色 (Token)！");

    const SYSTEM_ID = "xjzl-system";
    const flags = actor.flags[SYSTEM_ID] || {};
    const keys = Object.keys(flags).sort();

    // 2. 第一步：选择或输入 Key
    let optionsHtml = keys.map(k => `<option value="${k}">`).join("");

    const content1 = `
    <div class="form-group">
        <label>选择或输入标记名称 (Key):</label>
        <input list="flagKeys" id="keyInput" style="width:100%" placeholder="例如: neigong_shuyin"/>
        <datalist id="flagKeys">
            ${optionsHtml}
        </datalist>
    </div>
    <p style="font-size:0.9em; color:#666;">选中现有标记可查看当前值。</p>
    `;

    const step1 = await foundry.applications.api.DialogV2.wait({
        window: { title: `🔧 设置标记: ${actor.name}`, width: 350 },
        content: content1,
        buttons: [{
            action: "next", label: "下一步", icon: "fas fa-arrow-right",
            callback: (event, button, dialog) => dialog.element.querySelector("#keyInput").value
        }],
        rejectClose: false, 
        close: () => null
    });

    if (!step1) return;
    const targetKey = step1.trim();
    if (!targetKey) return;

    // 3. 第二步：输入新值
    const currentValue = flags[targetKey] !== undefined ? flags[targetKey] : 0;
    const currentDisplay = JSON.stringify(currentValue);

    const content2 = `
    <div class="form-group">
        <label>标记名称:</label>
        <input type="text" value="${targetKey}" disabled/>
    </div>
    <div class="form-group">
        <label>当前值:</label>
        <div style="font-family:monospace; background:rgba(0,0,0,0.05); padding:5px; border-radius:4px;">${currentDisplay}</div>
    </div>
    <hr>
    <div class="form-group">
        <label>新数值 / 公式:</label>
        <input type="text" id="valInput" placeholder="例如: 10, +5, -2" autofocus/>
        <p style="font-size:0.8em; color:#666;">
            <strong>覆盖:</strong> 输入纯数字 (如 10)<br>
            <strong>计算:</strong> 输入 +/- 前缀 (如 +5, -20)
        </p>
    </div>
    `;

    const step2 = await foundry.applications.api.DialogV2.wait({
        window: { title: `🔧 修改: ${targetKey}`, width: 350 },
        content: content2,
        buttons: [{
            action: "save", label: "执行", icon: "fas fa-check",
            callback: (event, button, dialog) => dialog.element.querySelector("#valInput").value
        }],
        rejectClose: false, 
        close: () => null
    });

    if (step2 === null) return;

    // 4. 解析逻辑
    const inputStr = step2.trim();
    if (!inputStr) return;

    // 判断是否是相对运算 (+/- 开头)
    const isRelative = inputStr.startsWith("+") || inputStr.startsWith("-");

    // 尝试转数字
    const numInput = Number(inputStr);

    if (isNaN(numInput)) {
        return ui.notifications.error("输入无效：请输入有效的数字！");
    }

    let finalVal = numInput;

    if (isRelative) {
        // 相对运算：当前值 + 输入值 (注意：Number("-5") 是 -5，所以直接相加即可)
        const currentNum = Number(currentValue) || 0;
        finalVal = currentNum + numInput;
    }
    // 否则直接覆盖，finalVal = numInput

    // 5. 执行更新
    await actor.setFlag(SYSTEM_ID, targetKey, finalVal);

    const typeStr = isRelative ? "计算更新" : "覆盖更新";
    ui.notifications.info(`${actor.name} [${targetKey}] ${typeStr}: ${finalVal}`);
})();

// 1. 获取选中的目标
const targets = Array.from(game.user.targets);
if (targets.length === 0) return ui.notifications.warn("请先在场景中选中至少一个目标！");

// ==========================================
// ⬇️ 在这里修改伤害的配置 ⬇️
// ==========================================
const EVENT_TITLE = "毒雾爆发";        // 修改：卡片显示的标题
const EVENT_DESC = "四周弥漫起刺鼻的毒气，防不胜防！"; // 修改：卡片里的说明文字
const DAMAGE_AMOUNT = 30;             // 修改：造成的面板伤害数值
const DAMAGE_TYPE = 'poison';         // 修改：伤害类型 (可选: waigong, neigong, fire, poison, bleed, mental, liushi)
// ==========================================

let resultHtml = "";

// 2. 遍历目标并应用伤害
for (const target of targets) {
    const tActor = target.actor;
    if (!tActor) continue;

    // 调用系统的伤害接口
    const dmgRes = await tActor.applyDamage({
        amount: DAMAGE_AMOUNT,
        type: DAMAGE_TYPE,
        attacker: null,     // 环境伤害无攻击者
        isHit: true,        // 默认必中
        source: 'extra'     // 标记为额外伤害，不触发常规的兵刃相接特效
    });

    // 拼接每个目标的扣血结果
    resultHtml += `<li><b>${tActor.name}</b> 承受了 <span style="color:red;">${dmgRes.finalDamage}</span> 点伤害<br><span style="color:#666; font-size:0.85em;">(实扣: 护体${dmgRes.hutiLost} / 气血${dmgRes.hpLost} / 内力${dmgRes.mpLost})</span></li>`;
}

// 3. 构建并发送聊天卡片
const content = `
<div class="xjzl-chat-card item-card">
    <header class="card-header" style="border-left: 4px solid #27ae60; background: rgba(0,0,0,0.05); padding: 5px;">
        <h3 style="color: #27ae60; margin: 0; font-weight: bold;"><i class="fas fa-skull-crossbones"></i> ${EVENT_TITLE}</h3>
    </header>
    <div class="card-content-wrapper" style="padding: 8px;">
        <div style="font-style: italic; color: #666; margin-bottom: 8px; font-size: 0.9em;">
            ${EVENT_DESC}
        </div>
        <ul style="margin: 0; padding-left: 20px; font-size: 0.9em; color: #444;">
            ${resultHtml}
        </ul>
    </div>
</div>`;

ChatMessage.create({ 
    speaker: { alias: "系统 / 环境" },
    content: content 
});
